#include <iostream>
#include <cmath>
#include <string>

long long maxTrianglePossible(long long n) {
    long long k = (long long)floor(sqrt((double)(n * 2)));
    return k;
}

long long triangleNumbers(long long x) {
    long long f = (x * (x + 1)) / 2;
    return f;
}

std::string funkyNumbers(long long n) {
    std::string funkyNumber = "NO";

    long long maxTriangle = maxTrianglePossible(n);

    for (long long i = maxTriangle; i > 0; i--) {
        long long firstTriangle = triangleNumbers(i);
        long long rem = n - firstTriangle;

        if (rem == 0) continue;

        long long secFactor = maxTrianglePossible(rem);
        long long secTriangle = triangleNumbers(secFactor);

        long long triangles = firstTriangle + secTriangle;

        if (triangles == n) {
            funkyNumber = "YES";
            break;
        }
    }

    return funkyNumber;
}

int main() {
    long long n;
    std::cin >> n;

    std::string res = funkyNumbers(n);
    std::cout << res << std::endl;

    return 0;
}

